// @ts-nocheck
// Customer account statement template (HTML for PDF rendering). No endpoint credentials included.
import type { Statement } from '../src/domain/contracts.js';
function escape(value: unknown): string {
  return String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
}
function safeStatement(statement: Statement): any {
  const clean = (record: Record<string, unknown>) => Object.fromEntries(Object.entries(record).map(([k,v]) => [k, typeof v === 'string' ? escape(v) : v]));
  return { user_details: clean(statement.user_details), transaction_records: statement.transaction_records.map(t => clean(t)) };
}
export function renderStatementHtml(statement: Statement): string {
// ─────────────────────────────────────────────────────────────────────────────

const statement_payload = safeStatement(statement);

const user         = statement_payload.user_details;
const transactions = statement_payload.transaction_records;

// ── Config ────────────────────────────────────────────────────────────────────
const LOGO    = 'data:image/png;base64,';
const LOGO_SM = LOGO;
const YEAR          = new Date().getFullYear();
const ROWS_P1 = 10;
const ROWS_PN = 13;

// ── Status badge map ──────────────────────────────────────────────────────────
const STATUSES = {
  SUCCESS:                    { bg:'#e6f4ee', color:'#166534', label:'Success' },
  REFUNDED:                   { bg:'#e6f4ee', color:'#166534', label:'Refunded' },
  FAILED:                     { bg:'#fef2f2', color:'#b91c1c', label:'Failed' },
  CANCELLED:                  { bg:'#fef2f2', color:'#b91c1c', label:'Cancelled' },
  PENDING:                    { bg:'#fffbeb', color:'#92400e', label:'Pending' },
  PROCESSING:                 { bg:'#fffbeb', color:'#92400e', label:'Processing' },
};

// ── Type icon map ─────────────────────────────────────────────────────────────
const TYPES = {
  DEPOSIT:             { icon:'arrow-down',    color:'#22c55e', label:'Deposit' },
  WITHDRAW:            { icon:'arrow-up',      color:'#f97316', label:'Withdrawal' },
  SWAP:                { icon:'exchange',      color:'#e66227', label:'Swap' },
  TRANSFER:            { icon:'transfer',      color:'#e66227', label:'User to User' },
  REVERSAL:            { icon:'arrow-back-up', color:'#e66227', label:'Reversal' },
};

const TYPE_ALIASES = {
  U2U_TRANSFER:       'TRANSFER',
};

// ── Helpers ───────────────────────────────────────────────────────────────────
function fmtDate(s) {
  if (!s) return '';
  const datePart = s.split('T')[0].split(' ')[0];
  const [y, m, d] = datePart.split('-').map(Number);
  return y + '-' + String(m).padStart(2, '0') + '-' + String(d).padStart(2, '0');
}

function fmtTime(s) {
  if (!s || (!s.includes('T') && !s.includes(' '))) return '';
  const d = new Date(s.replace(' ', 'T'));
  return isNaN(d) ? '' : d.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true, timeZone: 'UTC' });
}

function fmtNum(n) {
  if (n === null || n === undefined || n === '') return '';
  const [int, dec] = String(n).split('.');
  return int.replace(/\B(?=(\d{3})+(?!\d))/g, ',') + (dec !== undefined ? '.' + dec : '');
}

function toProperCase(s) {
  if (!s) return '';
  return s.replace(/\S+/g, function(word) {
    return word.split('-').map(function(part) {
      return part.charAt(0).toUpperCase() + part.slice(1).toLowerCase();
    }).join('-');
  });
}

function fmtDateLong(s) {
  if (!s) return '';
  const datePart = s.split('T')[0].split(' ')[0];
  const [y, m, d] = datePart.split('-').map(Number);
  return new Date(y, m - 1, d).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
}

function fmtAmt(amount, currency) {
  if (amount === null || amount === undefined || amount === '') return '';
  return currency ? currency + ' ' + fmtNum(amount) : fmtNum(amount);
}

function badge(status) {
  const key = (status || '').toUpperCase().replace(/\s+/g, '_');
  const s = STATUSES[key] || { bg: '#f3f4f6', color: '#4b5563', label: status };
  return '<span class="badge" style="background:' + s.bg + ';color:' + s.color + '">' + s.label + '</span>';
}

function typeIcon(name, color) {
  var stroke = 'stroke="' + color + '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" fill="none"';
  var paths = {
    'arrow-down': '<path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M12 5l0 14" ' + stroke + '/><path d="M18 13l-6 6" ' + stroke + '/><path d="M6 13l6 6" ' + stroke + '/>',
    'arrow-up':   '<path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M12 5l0 14" ' + stroke + '/><path d="M18 11l-6 -6" ' + stroke + '/><path d="M6 11l6 -6" ' + stroke + '/>',
    'gift':              '<path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M3 9a1 1 0 0 1 1-1h16a1 1 0 0 1 1 1v2a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V9z" ' + stroke + '/><path d="M12 8v13" ' + stroke + '/><path d="M19 12v7a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2v-7" ' + stroke + '/><path d="M7.5 8a2.5 2.5 0 0 1 0-5 4.8 8 0 0 1 4.5 5 4.8 8 0 0 1 4.5-5 2.5 2.5 0 0 1 0 5" ' + stroke + '/>',
    'rosette-discount':  '<path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M9 15l6-6" ' + stroke + '/><path d="M9 9.5a.5.5 0 1 0 1 0 .5.5 0 1 0-1 0" fill="' + color + '"/><path d="M14 14.5a.5.5 0 1 0 1 0 .5.5 0 1 0-1 0" fill="' + color + '"/><path d="M5 7.2a2.2 2.2 0 0 1 2.2-2.2h1a2.2 2.2 0 0 0 1.55-.64l.7-.7a2.2 2.2 0 0 1 3.12 0l.7.7a2.2 2.2 0 0 0 1.55.64h1a2.2 2.2 0 0 1 2.2 2.2v1a2.2 2.2 0 0 0 .64 1.55l.7.7a2.2 2.2 0 0 1 0 3.12l-.7.7a2.2 2.2 0 0 0-.64 1.55v1a2.2 2.2 0 0 1-2.2 2.2h-1a2.2 2.2 0 0 0-1.55.64l-.7.7a2.2 2.2 0 0 1-3.12 0l-.7-.7a2.2 2.2 0 0 0-1.55-.64h-1a2.2 2.2 0 0 1-2.2-2.2v-1a2.2 2.2 0 0 0-.64-1.55l-.7-.7a2.2 2.2 0 0 1 0-3.12l.7-.7a2.2 2.2 0 0 0 .64-1.55v-1" ' + stroke + '/>',
    'confetti':          '<path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M4 5h2" ' + stroke + '/><path d="M5 4v2" ' + stroke + '/><path d="M11.5 4l-.5 2" ' + stroke + '/><path d="M18 5h2" ' + stroke + '/><path d="M19 4v2" ' + stroke + '/><path d="M15 9l-1 1" ' + stroke + '/><path d="M18 13l2-.5" ' + stroke + '/><path d="M18 19h2" ' + stroke + '/><path d="M19 18v2" ' + stroke + '/><path d="M14 16.518l-6.518-6.518-4.39 9.58a1 1 0 0 0 1.329 1.329l9.579-4.39" ' + stroke + '/>',
    'transfer': '<path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M20 10h-16l5.5 -6" ' + stroke + '/><path d="M4 14h16l-5.5 6" ' + stroke + '/>',
    'exchange': '<path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M3 18a2 2 0 1 0 4 0a2 2 0 1 0 -4 0" ' + stroke + '/><path d="M17 6a2 2 0 1 0 4 0a2 2 0 1 0 -4 0" ' + stroke + '/><path d="M19 8v5a5 5 0 0 1 -5 5h-3l3 -3m0 6l-3 -3" ' + stroke + '/><path d="M5 16v-5a5 5 0 0 1 5 -5h3l-3 -3m0 6l3 -3" ' + stroke + '/>',
    'arrow-back-up':     '<path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M9 14l-4-4 4-4" ' + stroke + '/><path d="M5 10h11a4 4 0 1 1 0 8h-1" ' + stroke + '/>',
    'credit-card':       '<path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M3 8a3 3 0 0 1 3-3h12a3 3 0 0 1 3 3v8a3 3 0 0 1-3 3H6a3 3 0 0 1-3-3V8z" ' + stroke + '/><path d="M3 10h18" ' + stroke + '/><path d="M7 15h.01" ' + stroke + '/><path d="M11 15h2" ' + stroke + '/>',
    'calendar-repeat':   '<path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M12.5 21H6.5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v3" ' + stroke + '/><path d="M16 3v4" ' + stroke + '/><path d="M8 3v4" ' + stroke + '/><path d="M4 11h12" ' + stroke + '/><path d="M20 14l2 2h-3" ' + stroke + '/><path d="M20 18l2-2" ' + stroke + '/><path d="M19 16a3 3 0 1 0 2 5.236" ' + stroke + '/>',
    'circle-dotted':     '<path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M7.5 4.21l0 .01" ' + stroke + '/><path d="M4.21 7.5l0 .01" ' + stroke + '/><path d="M3 12l0 .01" ' + stroke + '/><path d="M4.21 16.5l0 .01" ' + stroke + '/><path d="M7.5 19.79l0 .01" ' + stroke + '/><path d="M12 21l0 .01" ' + stroke + '/><path d="M16.5 19.79l0 .01" ' + stroke + '/><path d="M19.79 16.5l0 .01" ' + stroke + '/><path d="M21 12l0 .01" ' + stroke + '/><path d="M19.79 7.5l0 .01" ' + stroke + '/><path d="M16.5 4.21l0 .01" ' + stroke + '/><path d="M12 3l0 .01" ' + stroke + '/>',
  };
  return '<svg width="13" height="13" viewBox="0 0 24 24" style="display:block;flex-shrink:0">' + (paths[name] || '') + '</svg>';
}

function typeLabel(type) {
  var norm = (type || '').toUpperCase().replace(/[\s-]+/g, '_');
  var key = TYPES[norm] ? norm : (TYPE_ALIASES[norm] || norm);
  var t = TYPES[key] || { color: '#9ca3af', label: type };
  return '<span style="font-size:10px;color:var(--text-main)">' + t.label + '</span>';
}

// ── Icons ─────────────────────────────────────────────────────────────────────
const ICON_USER     = '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#e66227" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" xmlns="http://www.w3.org/2000/svg"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>';
const ICON_CALENDAR = '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#e66227" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" xmlns="http://www.w3.org/2000/svg"><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/><path d="M8 14h.01M12 14h.01M16 14h.01M8 18h.01M12 18h.01"/></svg>';
const ICON_GLOBE    = '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#e66227" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="10"/><path d="M2 12h20M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>';
const ICON_INFO     = '<svg width="11" height="11" viewBox="0 0 24 24" fill="#9ca3af" xmlns="http://www.w3.org/2000/svg" style="flex-shrink:0;margin-top:1px"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-6h2v6zm0-8h-2V7h2v2z"/></svg>';

// ── Pagination ────────────────────────────────────────────────────────────────
const pages = [transactions.slice(0, ROWS_P1)];
for (var i = ROWS_P1; i < transactions.length; i += ROWS_PN) {
  pages.push(transactions.slice(i, i + ROWS_PN));
}
const totalPages = pages.length;

// ── Table ─────────────────────────────────────────────────────────────────────
const THEAD = [
  '<thead><tr>',
  '<th class="col-id">Transaction ID</th>',
  '<th class="col-date">Date</th>',
  '<th class="col-type">Type</th>',
  '<th class="col-status">Status</th>',
  '<th class="col-sent">Amount Sent</th>',
  '<th class="col-recv">Amount Received</th>',
  '<th class="col-rate">Rate</th>',
  '<th class="col-fee">Fee</th>',
  '<th class="col-bname">Recipient Name</th>',
  '<th class="col-bacct">Recipient Account</th>',
  '</tr></thead>'
].join('');

function renderRows(rows) {
  return rows.map(function(t) {
    var time  = fmtTime(t.transaction_date);
    var rateL1 = t.fx_rate ? '1 ' + t.sent_currency + ' =' : '';
    var rateL2 = t.fx_rate ? parseFloat(t.fx_rate).toFixed(2) + ' ' + t.received_currency : '';
    var feeCell = t.fee
      ? '<span class="line1">' + fmtNum(t.fee) + '</span><span class="line2">' + (t.sent_currency || '') + '</span>'
      : '<span style="color:#9ca3af">—</span>';
    return [
      '<tr>',
      '<td class="col-id"><span class="txn-id">' + (t.transaction_id || '') + '</span></td>',
      '<td class="col-date">',
        '<span class="line1">' + fmtDate(t.transaction_date) + '</span>',
        time ? '<span class="line2">' + time + '</span>' : '',
      '</td>',
      '<td class="col-type">' + typeLabel(t.transaction_type) + '</td>',
      '<td class="col-status">' + badge(t.status) + '</td>',
      '<td class="col-sent">'  + fmtAmt(t.amount_sent, t.sent_currency) + '</td>',
      '<td class="col-recv">'  + fmtAmt(t.amount_received, t.received_currency) + '</td>',
      '<td class="col-rate">',
        rateL1 ? '<span class="line1">' + rateL1 + '</span>' : '',
        rateL2 ? '<span class="line2">' + rateL2 + '</span>' : '',
      '</td>',
      '<td class="col-fee">' + feeCell + '</td>',
      '<td class="col-bname">' + toProperCase(t.beneficiary_name) + '</td>',
      '<td class="col-bacct">',
        '<span class="line1">' + (t.beneficiary_account || '') + '</span>',
        t.beneficiary_bank ? '<span class="line2">' + t.beneficiary_bank + '</span>' : '',
      '</td>',
      '</tr>'
    ].join('');
  }).join('');
}

// ── Common blocks ─────────────────────────────────────────────────────────────
const logoLg = '<div class="logo logo-lg"><div class="sf-logo sf-logo-lg" role="img" aria-label="SendFast"></div></div>';
const logoSm = '<div class="logo logo-sm"><div class="sf-logo sf-logo-sm" role="img" aria-label="SendFast"></div></div>';

// footerBlock now takes a flag to conditionally show the exchange-rate note
// (only rendered on page 1 and the final page)
function footerBlock(showNote) {
  return [
    '<div class="divider"></div>',
    showNote
      ? '<div class="footer-note">' + ICON_INFO + 'Exchange rates are locked in at the time of each transaction and shown to 2 decimal places. All dates and times are in UTC.</div>'
      : '',
    '<div class="footer">',
      '<div class="footer-logo">' + logoSm + '</div>',
      '<div class="footer-info">',
        '<div class="footer-copy">SendFast Inc. (fictional company, synthetic data) ' + YEAR + '</div>',
      '</div>',
      '<div class="footer-gen">',
        '<div class="gen-label">Statement generated on</div>',
        '<div class="gen-date">' + fmtDateLong(user.generated_on) + '</div>',
      '</div>',
    '</div>'
  ].join('');
}

const txnCount = transactions.length;
const headerFull = [
  '<div class="header-full">',
    logoLg,
    '<div class="header-right">',
      '<div class="header-addr">100 Sample Avenue, Toronto, ON, Canada</div>',
      '<div class="header-inquiry">For inquiries: <a href="https://sendfast.example/contact" style="color:#e66227;">https://sendfast.example/contact</a></div>',
    '</div>',
  '</div>',
  '<div class="title-block">',
    '<h1>Customer Account Statement</h1>',
  '</div>',
  '<div class="info-card">',
    '<div class="info-block">',
      '<div class="info-icon">' + ICON_USER + '</div>',
      '<div style="min-width:0">',
        '<div class="info-name">' + (user.full_name || '') + '</div>',
        '<div class="info-sub">'  + (user.address   || '') + '</div>',
        '<div class="info-sub">'  + (user.email     || '') + '</div>',
      '</div>',
    '</div>',
    '<div class="info-block info-block-right">',
      '<div>',
        '<div class="info-label">Statement Period</div>',
        '<div class="info-value">' + fmtDateLong(user.period_start) + ' – ' + fmtDateLong(user.period_end) + '</div>',
        '<div class="info-sub">' + txnCount + ' transaction' + (txnCount !== 1 ? 's' : '') + '</div>',
      '</div>',
    '</div>',
  '</div>',
  '<div class="divider" style="margin-bottom:12px"></div>',
  '<div class="section-heading">Transaction History</div>'
].join('');

function headerSlim(pn, total) {
  return [
    '<div class="header-slim">',
      logoSm,
      '<div class="page-indicator">Page <strong>' + pn + '</strong> of <strong>' + total + '</strong></div>',
    '</div>',
    '<div class="section-heading-cont">Transaction History (continued)</div>'
  ].join('');
}

// ── CSS ───────────────────────────────────────────────────────────────────────
const CSS = [
  '<link rel="preconnect" href="https://fonts.googleapis.com">',
  '<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>',
  '<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">',
  '<style>',
  '*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}',
  ':root{--brand-primary:#e66227;--brand-dark:#000000;--border:#e3e6e9;--text-main:#111827;--text-muted:#6b7280;--text-faint:#9ca3af;--page-bg:#F8F7F2}',
  'body{font-family:"Inter",-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:var(--page-bg);color:var(--text-main);font-size:11px;line-height:1.5}',
  '.page{background:#fff;width:100%;height:auto;min-height:1050px;margin:28px auto;padding:32px 36px;border-radius:12px;box-shadow:0 1px 4px rgba(67,76,84,0.08),0 4px 24px rgba(67,76,84,0.06);display:flex;flex-direction:column}',
  '.header-full{display:flex;justify-content:space-between;align-items:stretch;margin-bottom:14px}',
  '.header-slim{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;padding-bottom:11px;border-bottom:2px solid #e66227}',
  '.header-right{text-align:right;display:flex;flex-direction:column;align-items:flex-end}',
  '.header-addr{font-size:10px;color:#333333;margin-bottom:3px}',
  '.header-inquiry{font-size:10px;color:#333333}',
  '.header-inquiry a{color:#e66227}',
  '.gen-label{font-size:10px;color:var(--text-faint)}',
  '.gen-date{font-size:11px;font-weight:600;color:#000000}',
  '.page-indicator{font-size:10px;color:var(--text-faint)}',
  '.sf-logo{background:url(' + LOGO + ') no-repeat left center/contain}',
  '.sf-logo-lg{width:259px;height:38px}',
  '.sf-logo-sm{width:164px;height:24px}',
  '.logo-lg{display:inline-flex;flex-direction:column}',
  '.logo-divider{border-top:2px solid #e66227;margin-top:8px;width:100%}',
  '.title-block{margin-bottom:10px}',
  '.title-block h1{font-family:"Inter",sans-serif;font-size:20px;font-weight:700;color:var(--brand-dark);letter-spacing:-0.02em}',
  '.subtitle{font-size:10px;color:var(--text-muted);margin-top:2px}',
  '.info-card{display:grid;grid-template-columns:repeat(2,1fr);gap:0;margin-bottom:6px}',
  '.info-block{display:flex;align-items:flex-start;gap:11px;padding:14px 18px}',
  '.info-block:last-child{border-right:none}',
  '.info-block-right{justify-content:flex-end;text-align:right}',
  '.info-icon{width:34px;height:34px;background:#f4f5f6;border:1.5px solid #e66227;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-shrink:0}',
  '.info-label{font-size:10px;color:var(--text-faint);font-weight:500;margin-bottom:2px;text-transform:uppercase;letter-spacing:0.04em}',
  '.info-value{font-size:11px;font-weight:600;color:var(--text-main)}',
  '.info-name{font-size:16px;font-weight:700;color:var(--text-main);letter-spacing:-0.01em;margin-bottom:3px}',
  '.info-sub{font-size:10px;color:var(--text-muted);margin-top:1px}',
  '.section-heading{font-size:12px;font-weight:700;color:var(--brand-dark);margin-bottom:10px}',
  '.section-heading-cont{font-size:11px;font-weight:600;color:var(--text-muted);margin-bottom:10px}',
  'table{width:100%;border-collapse:collapse;table-layout:fixed;border:1px solid #434c54}',
  'thead tr{border-bottom:2px solid #434c54;background:#f4f5f6}',
  'th{font-size:9.5px;font-weight:600;color:#434c54;text-align:left;padding:7px 8px;white-space:normal;word-break:normal;overflow:hidden;vertical-align:top;border-right:1px solid #434c54}',
  'th:last-child{border-right:none}',
  'td{font-size:10.5px;color:var(--text-main);padding:7px 8px;border-bottom:1px solid #434c54;border-right:1px solid #434c54;vertical-align:top;white-space:normal;word-break:break-word;overflow-wrap:break-word;overflow:hidden}',
  'td:last-child{border-right:none}',
  'tr:last-child td{border-bottom:none}',
  '.col-id{width:12%}',
  '.col-date{width:9%}',
  '.col-type{width:9%;text-align:center}',
  '.col-status{width:9%;text-align:center}',
  '.col-sent{width:9%}',
  '.col-recv{width:9%}',
  '.col-rate{width:9%}',
  '.col-fee{width:6%}',
  '.col-bname{width:14%}',
  '.col-bacct{width:14%}',
  '.line1{display:block}',
  '.line2{display:block;color:var(--text-muted);font-size:10px;margin-top:2px}',
  '.txn-id{font-size:10px;color:#434c54;font-family:"Inter",-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;word-break:break-all}',
  '.badge{display:inline;font-size:10px;font-weight:600;white-space:normal;word-break:normal;overflow-wrap:normal}',
  '.type-cell{display:inline-flex;flex-direction:column;align-items:center;gap:2px;font-size:10px;color:var(--text-main)}',
  '.type-icon{display:flex;justify-content:center}',
  '.footer-note{display:flex;align-items:flex-start;gap:6px;font-size:10px;font-style:italic;color:var(--text-muted);margin-top:10px;padding:0}',
  '.divider{border-top:2px solid #e66227;margin-top:12px}',
  '.footer{display:flex;align-items:flex-start;gap:20px;margin-top:auto;padding-top:18px}',
  '.footer-logo{flex-shrink:0}',
  '.footer-info{flex:1;display:flex;align-items:center;gap:8px}',
  '.footer-copy{font-size:10px;color:var(--text-faint)}',
  '.footer-copy a{color:inherit}',
  '.footer-gen{flex-shrink:0;text-align:right}',
  // While paginating, pages take their exact printed size so rows are measured as they will print.
  'html.paginate,html.paginate body{width:210mm}',
  'html.paginate .page{width:210mm;height:297mm;margin:0;padding:10mm 12mm;border-radius:0;box-shadow:none;overflow:hidden}',
  '@page{size:A4;margin:0}',
  '@media print{',
  'html,body{width:210mm;height:297mm;margin:0;padding:0;background:#fff}',
  '.page{width:210mm;height:297mm;margin:0;padding:10mm 12mm;border-radius:0;box-shadow:none;overflow:hidden;page-break-after:always}',
  '.page:last-child{page-break-after:avoid}',
  '}',
  '</style>'
].join('');

// ── Render pages ──────────────────────────────────────────────────────────────
const renderedPages = pages.map(function(rows, idx) {
  var pn     = idx + 1;
  var header = pn === 1 ? headerFull : headerSlim(pn, totalPages);
  return [
    '<div class="page">',
      header,
      '<div style="flex:1">',
        '<table>' + THEAD + '<tbody>' + renderRows(rows) + '</tbody></table>',
      '</div>',
      footerBlock(pn === 1 || pn === totalPages),
    '</div>'
  ].join('');
}).join('');

// ── Measured pagination ──────────────────────────────────────────────────────
// The fixed ROWS_P1 / ROWS_PN split above is only a fallback. In the browser that prints the PDF,
// this script moves rows between pages by their real rendered height, so tall rows (long IDs,
// wrapped amounts) can never push the footer off the page. It then fills in "Page X of Y" and
// keeps the exchange-rate note on the first and last pages, as before.
const TEMPLATES = [
  '<template id="tpl-header-full">' + headerFull + '</template>',
  '<template id="tpl-header-slim">' + headerSlim('', '') + '</template>',
  '<template id="tpl-thead">' + THEAD + '</template>',
  '<template id="tpl-footer">' + footerBlock(true) + '</template>'
].join('');
// Plain text on purpose: build tools rewrite real functions (e.g. inject helpers), which would break in the PDF.
const PAGINATE_SCRIPT = '<script>' + [
  '(function () {',
  '  var doc = document, root = doc.documentElement;',
  '  function tpl(id) { return doc.getElementById(id).innerHTML; }',
  '  function paginate() {',
  '    root.classList.add("paginate");',
  '    var old = [].slice.call(doc.querySelectorAll(".page"));',
  '    var rows = [].slice.call(doc.querySelectorAll(".page tbody tr"));',
  '    var made = [], page, body;',
  '    function newPage(first) {',
  '      page = doc.createElement("div");',
  '      page.className = "page";',
  '      page.innerHTML = tpl(first ? "tpl-header-full" : "tpl-header-slim")',
  '        + "<div style=\\"flex:1\\"><table>" + tpl("tpl-thead") + "<tbody></tbody></table></div>" + tpl("tpl-footer");',
  '      old[0].parentNode.insertBefore(page, old[0]);',
  '      body = page.querySelector("tbody");',
  '      /* The exchange-rate note belongs on the first and last pages only; middle pages are measured without it. */',
  '      if (!first) note(page, false);',
  '      made.push(page);',
  '    }',
  '    function note(p, on) {',
  '      var el = p.querySelector(".footer-note");',
  '      if (!on && el) el.parentNode.removeChild(el);',
  '      var dividers = p.querySelectorAll(".divider");',
  '      if (on && !el) dividers[dividers.length - 1].insertAdjacentHTML("afterend", noteHtml);',
  '    }',
  '    function overflows(p) { return p.scrollHeight > p.clientHeight + 1; }',
  '    var noteHtml = doc.querySelector("#tpl-footer").content.querySelector(".footer-note").outerHTML;',
  '    newPage(true);',
  '    rows.forEach(function (tr) {',
  '      body.appendChild(tr);',
  '      /* Overflowing pages keep at least one row; otherwise the row moves to a fresh page. */',
  '      if (overflows(page) && body.children.length > 1) {',
  '        body.removeChild(tr); newPage(false); body.appendChild(tr);',
  '      }',
  '    });',
  '    /* The last page also gets the note; if that no longer fits, its final rows move to one more page. */',
  '    if (made.length > 1) {',
  '      note(page, true);',
  '      if (overflows(page) && body.children.length > 1) {',
  '        var spill = [];',
  '        while (overflows(page) && body.children.length > 1) spill.unshift(body.removeChild(body.lastElementChild));',
  '        note(page, false); newPage(false); note(page, true);',
  '        spill.forEach(function (tr) { body.appendChild(tr); });',
  '      }',
  '    }',
  '    old.forEach(function (p) { p.parentNode.removeChild(p); });',
  '    made.forEach(function (p, i) {',
  '      var nums = p.querySelectorAll(".page-indicator strong");',
  '      if (nums.length === 2) { nums[0].textContent = String(i + 1); nums[1].textContent = String(made.length); }',
  '    });',
  '    return made.length;',
  '  }',
  '  var total = paginate();',
  '  function done(n) { root.setAttribute("data-paginated", String(n)); }',
  '  /* Re-measure once the web font has loaded; the PDF service waits for data-paginated before printing. */',
  '  if (doc.fonts && doc.fonts.ready) doc.fonts.ready.then(function () { done(paginate()); }, function () { done(total); });',
  '  else done(total);',
  '})();'
].join('\n') + '</script>';

const html = '<!DOCTYPE html><html><head><meta charset="UTF-8">' + CSS + '</head><body>' + renderedPages + TEMPLATES + PAGINATE_SCRIPT + '</body></html>';

return html;
}
